"""MIF v2.0 data models."""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any


@dataclass
class EntityReference:
    name: str
    entity_type: str = "unknown"
    confidence: float = 1.0

    def to_dict(self) -> dict:
        d: dict[str, Any] = {"name": self.name}
        d["entity_type"] = self.entity_type
        d["confidence"] = self.confidence
        return d

    @classmethod
    def from_dict(cls, data: dict) -> EntityReference:
        return cls(
            name=data["name"],
            entity_type=data.get("entity_type", "unknown"),
            confidence=data.get("confidence", 1.0),
        )


@dataclass
class Embedding:
    model: str
    dimensions: int
    vector: list[float]
    normalized: bool = True

    def to_dict(self) -> dict:
        return {
            "model": self.model,
            "dimensions": self.dimensions,
            "vector": self.vector,
            "normalized": self.normalized,
        }

    @classmethod
    def from_dict(cls, data: dict) -> Embedding:
        return cls(
            model=data["model"],
            dimensions=data["dimensions"],
            vector=data["vector"],
            normalized=data.get("normalized", True),
        )


@dataclass
class Source:
    source_type: str = ""
    session_id: str | None = None
    agent_name: str | None = None

    def to_dict(self) -> dict:
        d: dict[str, Any] = {}
        if self.source_type:
            d["source_type"] = self.source_type
        if self.session_id:
            d["session_id"] = self.session_id
        if self.agent_name:
            d["agent_name"] = self.agent_name
        return d

    @classmethod
    def from_dict(cls, data: dict) -> Source:
        return cls(
            source_type=data.get("source_type", ""),
            session_id=data.get("session_id"),
            agent_name=data.get("agent_name") or data.get("agent"),
        )


@dataclass
class Memory:
    id: str
    content: str
    created_at: str
    memory_type: str = "observation"
    updated_at: str | None = None
    tags: list[str] = field(default_factory=list)
    entities: list[EntityReference] = field(default_factory=list)
    metadata: dict[str, Any] = field(default_factory=dict)
    embeddings: Embedding | None = None
    source: Source | None = None
    parent_id: str | None = None
    related_memory_ids: list[str] = field(default_factory=list)
    agent_id: str | None = None
    external_id: str | None = None
    version: int = 1
    _extra: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "id": self.id,
            "content": self.content,
            "created_at": self.created_at,
        }
        if self.memory_type and self.memory_type != "observation":
            d["memory_type"] = self.memory_type
        if self.updated_at:
            d["updated_at"] = self.updated_at
        if self.tags:
            d["tags"] = self.tags
        if self.entities:
            d["entities"] = [e.to_dict() for e in self.entities]
        if self.metadata:
            d["metadata"] = self.metadata
        if self.embeddings:
            d["embeddings"] = self.embeddings.to_dict()
        if self.source:
            d["source"] = self.source.to_dict()
        if self.parent_id is not None:
            d["parent_id"] = self.parent_id
        if self.related_memory_ids:
            d["related_memory_ids"] = self.related_memory_ids
        if self.agent_id is not None:
            d["agent_id"] = self.agent_id
        if self.external_id is not None:
            d["external_id"] = self.external_id
        if self.version != 1:
            d["version"] = self.version
        # Preserve any unknown fields from the source
        for k, v in self._extra.items():
            if k not in d:
                d[k] = v
        return d

    @classmethod
    def from_dict(cls, data: dict) -> Memory:
        known = {
            "id", "content", "created_at", "memory_type", "updated_at",
            "tags", "entities", "metadata", "embeddings", "source",
            "parent_id", "related_memory_ids", "agent_id", "external_id", "version",
        }
        extra = {k: v for k, v in data.items() if k not in known}
        return cls(
            id=data.get("id", str(uuid.uuid4())),
            content=data.get("content", ""),
            created_at=data.get("created_at", datetime.now(timezone.utc).isoformat()),
            memory_type=data.get("memory_type", "observation"),
            updated_at=data.get("updated_at"),
            tags=data.get("tags", []),
            entities=[EntityReference.from_dict(e) for e in data.get("entities", [])],
            metadata=data.get("metadata", {}),
            embeddings=Embedding.from_dict(data["embeddings"]) if data.get("embeddings") else None,
            source=Source.from_dict(data["source"]) if data.get("source") else None,
            parent_id=data.get("parent_id"),
            related_memory_ids=data.get("related_memory_ids", []),
            agent_id=data.get("agent_id"),
            external_id=data.get("external_id"),
            version=data.get("version", 1),
            _extra=extra,
        )


@dataclass
class GraphEntity:
    id: str
    name: str
    types: list[str] = field(default_factory=list)
    attributes: dict[str, Any] = field(default_factory=dict)
    summary: str | None = None
    created_at: str | None = None
    last_seen_at: str | None = None
    _extra: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict:
        d: dict[str, Any] = {"id": self.id, "name": self.name}
        if self.types:
            d["types"] = self.types
        if self.attributes:
            d["attributes"] = self.attributes
        if self.summary:
            d["summary"] = self.summary
        if self.created_at:
            d["created_at"] = self.created_at
        if self.last_seen_at:
            d["last_seen_at"] = self.last_seen_at
        for k, v in self._extra.items():
            if k not in d:
                d[k] = v
        return d

    @classmethod
    def from_dict(cls, data: dict) -> GraphEntity:
        known = {"id", "name", "types", "attributes", "summary", "created_at", "last_seen_at"}
        return cls(
            id=data["id"],
            name=data["name"],
            types=data.get("types", []),
            attributes=data.get("attributes", {}),
            summary=data.get("summary"),
            created_at=data.get("created_at"),
            last_seen_at=data.get("last_seen_at"),
            _extra={k: v for k, v in data.items() if k not in known},
        )


@dataclass
class GraphRelationship:
    id: str
    source_entity_id: str
    target_entity_id: str
    relation_type: str
    context: str | None = None
    confidence: float | None = None
    created_at: str | None = None
    invalidated_at: str | None = None
    _extra: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "id": self.id,
            "source_entity_id": self.source_entity_id,
            "target_entity_id": self.target_entity_id,
            "relation_type": self.relation_type,
        }
        if self.context:
            d["context"] = self.context
        if self.confidence is not None:
            d["confidence"] = self.confidence
        if self.created_at:
            d["created_at"] = self.created_at
        if self.invalidated_at is not None:
            d["invalidated_at"] = self.invalidated_at
        for k, v in self._extra.items():
            if k not in d:
                d[k] = v
        return d

    @classmethod
    def from_dict(cls, data: dict) -> GraphRelationship:
        known = {
            "id", "source_entity_id", "target_entity_id", "relation_type",
            "context", "confidence", "created_at", "invalidated_at",
        }
        return cls(
            id=data["id"],
            source_entity_id=data["source_entity_id"],
            target_entity_id=data["target_entity_id"],
            relation_type=data["relation_type"],
            context=data.get("context"),
            confidence=data.get("confidence"),
            created_at=data.get("created_at"),
            invalidated_at=data.get("invalidated_at"),
            _extra={k: v for k, v in data.items() if k not in known},
        )


@dataclass
class KnowledgeGraph:
    entities: list[GraphEntity] = field(default_factory=list)
    relationships: list[GraphRelationship] = field(default_factory=list)
    _extra: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "entities": [e.to_dict() for e in self.entities],
            "relationships": [r.to_dict() for r in self.relationships],
        }
        for k, v in self._extra.items():
            if k not in d:
                d[k] = v
        return d

    @classmethod
    def from_dict(cls, data: dict) -> KnowledgeGraph:
        known = {"entities", "relationships"}
        return cls(
            entities=[GraphEntity.from_dict(e) for e in data.get("entities", [])],
            relationships=[GraphRelationship.from_dict(r) for r in data.get("relationships", [])],
            _extra={k: v for k, v in data.items() if k not in known},
        )


@dataclass
class MifDocument:
    mif_version: str = "2.0"
    memories: list[Memory] = field(default_factory=list)
    generator: dict[str, str] | None = None
    export_meta: dict[str, Any] | None = None
    knowledge_graph: KnowledgeGraph | None = None
    vendor_extensions: dict[str, Any] = field(default_factory=dict)
    _extra: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict:
        d: dict[str, Any] = {
            "mif_version": self.mif_version,
            "memories": [m.to_dict() for m in self.memories],
        }
        if self.generator:
            d["generator"] = self.generator
        if self.export_meta:
            d["export_meta"] = self.export_meta
        if self.knowledge_graph:
            d["knowledge_graph"] = self.knowledge_graph.to_dict()
        if self.vendor_extensions:
            d["vendor_extensions"] = self.vendor_extensions
        # Preserve unknown top-level fields
        for k, v in self._extra.items():
            if k not in d:
                d[k] = v
        return d

    @classmethod
    def from_dict(cls, data: dict) -> MifDocument:
        known = {
            "mif_version", "memories", "generator", "export_meta",
            "knowledge_graph", "vendor_extensions",
        }
        kg_data = data.get("knowledge_graph")
        return cls(
            mif_version=data.get("mif_version", "2.0"),
            memories=[Memory.from_dict(m) for m in data.get("memories", [])],
            generator=data.get("generator"),
            export_meta=data.get("export_meta"),
            knowledge_graph=KnowledgeGraph.from_dict(kg_data) if kg_data else None,
            vendor_extensions=data.get("vendor_extensions", {}),
            _extra={k: v for k, v in data.items() if k not in known},
        )

/** MIF v2.0 data models. */

import { randomUUID } from "crypto";

export interface EntityReference {
  name: string;
  entity_type?: string;
  confidence?: number;
  [key: string]: unknown;
}

export interface Embedding {
  model: string;
  dimensions: number;
  vector: number[];
  normalized?: boolean;
}

export interface Source {
  source_type?: string;
  session_id?: string;
  agent_name?: string;
  [key: string]: unknown;
}

export interface Memory {
  id: string;
  content: string;
  created_at: string;
  memory_type?: string;
  updated_at?: string;
  tags?: string[];
  entities?: EntityReference[];
  metadata?: Record<string, unknown>;
  embeddings?: Embedding;
  source?: Source;
  parent_id?: string | null;
  related_memory_ids?: string[];
  agent_id?: string | null;
  external_id?: string | null;
  version?: number;
  [key: string]: unknown;
}

export interface GraphEntity {
  id: string;
  name: string;
  types?: string[];
  attributes?: Record<string, unknown>;
  summary?: string;
  created_at?: string;
  last_seen_at?: string;
  [key: string]: unknown;
}

export interface GraphRelationship {
  id: string;
  source_entity_id: string;
  target_entity_id: string;
  relation_type: string;
  context?: string;
  confidence?: number;
  created_at?: string;
  invalidated_at?: string | null;
  [key: string]: unknown;
}

export interface KnowledgeGraph {
  entities?: GraphEntity[];
  relationships?: GraphRelationship[];
  [key: string]: unknown;
}

export interface MifDocument {
  mif_version: string;
  memories: Memory[];
  generator?: { name: string; version: string };
  export_meta?: Record<string, unknown>;
  knowledge_graph?: KnowledgeGraph | null;
  vendor_extensions?: Record<string, unknown>;
  [key: string]: unknown;
}

/** Create a minimal Memory object with defaults. */
export function createMemory(partial: Partial<Memory> & { content: string }): Memory {
  return {
    ...partial,
    id: partial.id || randomUUID(),
    content: partial.content,
    created_at: partial.created_at || new Date().toISOString(),
    memory_type: partial.memory_type || "observation",
  };
}

/** Create a minimal MifDocument. */
export function createDocument(memories: Memory[] = []): MifDocument {
  return {
    mif_version: "2.0",
    memories,
  };
}

"""MIF MCP Server — expose MIF tools via Model Context Protocol."""

from __future__ import annotations

import json

from mif.registry import AdapterRegistry, load, dump, validate, validate_deep

_registry = AdapterRegistry()


def create_server():
    """Create and return a FastMCP server with MIF tools."""
    from mcp.server.fastmcp import FastMCP

    mcp = FastMCP(
        "MIF Tools",
        description="Memory Interchange Format — convert, validate, and inspect AI agent memories",
    )

    @mcp.tool()
    def export_memories(
        data: str,
        from_format: str | None = None,
    ) -> str:
        """Convert memories from any supported format to MIF v2 JSON.

        Args:
            data: Input data string (JSON, markdown, etc.)
            from_format: Source format ID (auto-detected if omitted).
                         Options: shodh, mem0, crewai, langchain, generic, markdown
        """
        doc = load(data, format=from_format)
        return dump(doc, format="shodh")

    @mcp.tool()
    def import_memories(
        data: str,
        to_format: str = "shodh",
    ) -> str:
        """Convert MIF v2 JSON to a target format.

        Args:
            data: MIF v2 JSON string
            to_format: Target format ID.
                       Options: shodh, mem0, crewai, langchain, generic, markdown
        """
        doc = load(data, format="shodh")
        return dump(doc, format=to_format)

    @mcp.tool()
    def validate_memories(data: str) -> str:
        """Validate a MIF JSON document against the schema and run semantic checks.

        Args:
            data: MIF JSON string to validate

        Returns:
            JSON object with validation results
        """
        schema_ok, schema_errors = validate(data)
        if not schema_ok:
            return json.dumps({
                "valid": False,
                "schema_errors": schema_errors,
            }, indent=2)

        deep_ok, deep_warnings = validate_deep(data)
        doc = load(data)
        return json.dumps({
            "valid": True,
            "schema_valid": True,
            "semantic_valid": deep_ok,
            "semantic_warnings": deep_warnings,
            "summary": {
                "memories": len(doc.memories),
                "has_graph": doc.knowledge_graph is not None,
                "has_extensions": bool(doc.vendor_extensions),
            },
        }, indent=2)

    @mcp.tool()
    def list_formats() -> str:
        """List all available memory format adapters.

        Returns:
            JSON array of format objects with name and format_id
        """
        formats = _registry.list_formats()
        return json.dumps(formats, indent=2)

    @mcp.tool()
    def inspect_memories(
        data: str,
        from_format: str | None = None,
    ) -> str:
        """Show a summary of a memory file.

        Args:
            data: Input data string
            from_format: Source format ID (auto-detected if omitted)
        """
        doc = load(data, format=from_format)

        types: dict[str, int] = {}
        all_tags: set[str] = set()
        for m in doc.memories:
            types[m.memory_type] = types.get(m.memory_type, 0) + 1
            all_tags.update(m.tags)

        result = {
            "mif_version": doc.mif_version,
            "memory_count": len(doc.memories),
            "types": types,
            "tags": sorted(all_tags),
            "has_graph": doc.knowledge_graph is not None,
            "has_extensions": bool(doc.vendor_extensions),
        }
        if doc.generator:
            result["generator"] = doc.generator

        return json.dumps(result, indent=2)

    return mcp


def main():
    """Run the MIF MCP server."""
    server = create_server()
    server.run()


if __name__ == "__main__":
    main()

